DECLARE
  para_StuID PLS_INTEGER := -3;
  para_ResTypeID PLS_INTEGER := 2;
  para_ResTypeDescription VARCHAR2(100) := '%';
BEGIN
  DELETE FROM Restaurant_Type
  WHERE ResTypeDescription LIKE para_ResTypeDescription
    AND ResTypeID <> para_ResTypeID;
END;
/
SELECT ResTypeID, ResTypeName, ResTypeDescription FROM Restaurant_Type ORDER BY ResTypeID;
